  const [campaigns, setCampaigns] = useState<ManagedCampaign[]>([]); const [syncedAt, setSyncedAt] = useState(""); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const [recommendations, setRecommendations] = useState<ManagedRecommendation[]>([]); const [optimizationScore, setOptimizationScore] = useState<number | null>(null); const [optimizationScoreUrl, setOptimizationScoreUrl] = useState<string | null>(null); const [recommendationsLoading, setRecommendationsLoading] = useState(false); const [recommendationsLoaded, setRecommendationsLoaded] = useState(false); const [recommendationsError, setRecommendationsError] = useState<string | null>(null); const [recommendationFilter, setRecommendationFilter] = useState<"all" | ManagedRecommendationCategory>("all");
