  const [view, setView] = useState<ManagementView>("campaigns"); const [selectedId, setSelectedId] = useState(""); const [selectedAdGroupId, setSelectedAdGroupId] = useState(""); const [selectedAdId, setSelectedAdId] = useState(""); const [values, setValues] = useState<Record<string, unknown>>({}); const [baselineOverrides, setBaselineOverrides] = useState<Record<string, unknown>>({}); const creator = currentUser.displayName; const [request, setRequest] = useState<AdsChangeSetRecord | null>(null); const [resumeData, setResumeData] = useState<AdsChangeSetRecord | null>(null); const [saveState, setSaveState] = useState<SaveState>("idle"); const [submitting, setSubmitting] = useState(false); const first = useRef(true); const lastSavedKey = useRef(""); const resumed = useRef(false); const requestRef = useRef<AdsChangeSetRecord | null>(null); const saveInFlight = useRef(false);
