  const saveDraft = useCallback(async () => { if (!canEdit || saveInFlight.current) return; saveInFlight.current = true; setSaveState("saving"); setError(null); const activeRequest = requestRef.current; const editorContext: DraftEditorContext = { view: view === "ads" ? "ads" : view === "ad_groups" ? "ad_groups" : "campaigns", campaignId: campaign?.id || selectedId, ...(selectedAdGroupId ? { adGroupId: selectedAdGroupId } : {}), ...(selectedAdId ? { adId: selectedAdId } : {}) }; try { const response = await fetch(activeRequest ? `/api/ads-management/change-requests/${activeRequest.id}` : "/api/ads-management/change-requests", { method: activeRequest ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(activeRequest ? { version: activeRequest.version, changes, editorContext } : { accountId, accountName, title: `${campaign?.name || "Campaign"} changes`, reason: "", baselineCapturedAt: syncedAt, changes, editorContext }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error); lastSavedKey.current = draftKey; requestRef.current = payload; setRequest(payload); setSaveState("saved"); } catch (e) { setSaveState("failed"); setError(e instanceof Error ? e.message : "Autosave failed."); } finally { saveInFlight.current = false; } }, [accountId, accountName, campaign?.id, campaign?.name, canEdit, changes, draftKey, selectedAdGroupId, selectedAdId, selectedId, syncedAt, view]);
