function ServingStatus({ status, reasons }: { status: string; reasons: string[] }) { return <><span className={status === "ELIGIBLE" ? "text-green-700" : status === "NOT_ELIGIBLE" ? "text-red-700" : "text-amber-700"}>{formatStatus(status)}</span>{reasons.length ? <span className="mt-1 block max-w-52 text-[11px] text-slate-500">{reasons.slice(0, 2).map(formatStatus).join(" · ")}</span> : null}</>; }
function campaignMetricSummary(campaign: ManagedCampaign) { return metricSummary({ costMicros: String((campaign.performance ?? []).reduce((sum, point) => sum + Number(point.costMicros), 0)), impressions: (campaign.performance ?? []).reduce((sum, point) => sum + point.impressions, 0), clicks: (campaign.performance ?? []).reduce((sum, point) => sum + point.clicks, 0), conversions: (campaign.performance ?? []).reduce((sum, point) => sum + point.conversions, 0), interactions: (campaign.performance ?? []).reduce((sum, point) => sum + point.interactions, 0) }); }
