function adTableSummary(ad: ManagedAd) { const textField = (ending: string) => ad.fields.find((field) => field.fieldKey.endsWith(ending)); const textAssets = (field: ManagedFieldValue | undefined) => Array.isArray(field?.value) ? (field.value as ManagedAdTextAsset[]).map((asset) => asset.text).filter(Boolean) : []; const headlines = textAssets(textField("headlines")); const descriptions = textAssets(textField("descriptions")); const finalUrl = String(ad.fields.find((field) => field.fieldKey === "ad.final_url")?.value || ""); const path1 = String(ad.fields.find((field) => field.fieldKey === "ad.path1" || field.fieldKey.endsWith("breadcrumb1"))?.value || ""); const path2 = String(ad.fields.find((field) => field.fieldKey === "ad.path2" || field.fieldKey.endsWith("breadcrumb2"))?.value || ""); let displayUrl = finalUrl || "No final URL"; try { const parsed = new URL(finalUrl); displayUrl = `${parsed.hostname}${path1 ? `/${path1}` : ""}${path2 ? `/${path2}` : ""}`; } catch {} return { headlines: headlines.slice(0, 3).join(" | ") || ad.name, moreHeadlines: Math.max(0, headlines.length - 3), displayUrl, descriptions: descriptions.slice(0, 2).join(" ") || "No description assets returned." }; }
