  const filters: Array<{ key: "all" | ManagedRecommendationCategory; label: string }> = [{ key: "all", label: "All" }, { key: "repairs", label: "Repairs" }, { key: "bidding_budgets", label: "Bidding & budgets" }, { key: "keywords_targeting", label: "Keywords & targeting" }, { key: "ads_assets", label: "Ads & assets" }, { key: "measurement", label: "Measurement" }];
