    {loading ? <div className="grid min-h-64 place-items-center rounded-2xl border bg-white"><p className="flex items-center gap-2 text-sm text-slate-600"><Loader2Icon className="size-4 animate-spin" />Loading Google recommendations…</p></div> : null}
    {error ? <div className="rounded-2xl border border-red-200 bg-red-50 p-5 text-sm text-red-700"><AlertTriangleIcon className="mr-2 inline size-4" />{error}</div> : null}
