    {!loading && !error && !visible.length ? <div className="rounded-2xl border border-dashed bg-white p-10 text-center"><CheckCircle2Icon className="mx-auto size-8 text-green-600" /><h3 className="mt-3 font-semibold">No active recommendations in this category</h3><p className="mt-1 text-sm text-slate-500">Google did not return any current recommendation for the selected filter.</p></div> : null}
    {!loading && !error && optimizationScoreUrl && visibleGoogleAdsGuidance.length ? <section className="space-y-4"><div><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Google Ads website guidance</p><h3 className="mt-1 text-2xl font-semibold">View-only recommendations</h3><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-600">Google&apos;s website can show additional setup and eligibility guidance that is not exposed as a live Recommendation API resource. These cards intentionally have no Apply button here; Google confirms current applicability after you open the recommendation.</p></div><div className={`grid gap-4 ${displayMode === "cards" ? "xl:grid-cols-2 2xl:grid-cols-3" : "grid-cols-1"}`}>{visibleGoogleAdsGuidance.map((item) => <GoogleAdsViewOnlyCard key={item.title} item={item} onView={() => setSelectedDetail({ kind: "google_only", item })} />)}</div></section> : null}
    {selectedDetail ? <RecommendationDetailPanel detail={selectedDetail} googleUrl={optimizationScoreUrl} onClose={() => setSelectedDetail(null)} onCreateRequest={(items) => { setSelectedDetail(null); prepareApply(items); }} /> : null}
