function GoogleAdsViewOnlyCard({ item, onView }: { item: GoogleAdsViewOnlyGuidanceItem; onView: () => void }) { return <article className="flex min-h-56 flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex-1 p-5"><div className="flex items-center justify-between gap-3"><span className="grid size-9 place-items-center rounded-full bg-slate-100 text-slate-600"><ArrowUpRightIcon className="size-4" /></span><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">Google Ads view-only</span></div><p className="mt-4 text-xs font-semibold uppercase tracking-wide text-slate-500">{recommendationCategoryLabel(item.category)}</p><h4 className="mt-1 text-lg font-semibold">{item.title}</h4><p className="mt-2 text-sm leading-6 text-slate-600">{item.description}</p></div><div className="flex justify-end border-t px-5 py-3"><Button type="button" size="sm" variant="outline" onClick={onView}>View recommendation</Button></div></article>; }
function RecommendationCard({ recommendations, featured, compact, onView, onApply }: { recommendations: ManagedRecommendation[]; featured: boolean; compact: boolean; onView: () => void; onApply: () => void }) { const recommendation = recommendations[0]; const delta = recommendationGroupDelta(recommendations); const uplift = formatRecommendationUplift(recommendationGroupUplift(recommendations)); const campaignNames = [...new Set(recommendations.flatMap((item) => item.campaignName ? [item.campaignName] : []))]; return <article className={`flex flex-col overflow-hidden rounded-2xl border bg-white shadow-sm ${compact ? "min-h-72" : "min-h-0"}`}>{featured ? <div className="bg-blue-50 px-5 py-2 text-xs font-semibold uppercase tracking-wide text-blue-700">Top API recommendation for you</div> : null}<div className="flex-1 p-5"><div className="flex items-start justify-between gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-full bg-blue-50 text-blue-700"><LightbulbIcon className="size-5" /></span>{uplift ? <span className="rounded-full bg-blue-50 px-3 py-1 text-sm font-semibold text-blue-700">{uplift}</span> : null}</div><p className="mt-4 text-xs font-semibold uppercase tracking-wide text-slate-500">{recommendationCategoryLabel(recommendation.category)}</p><h3 className="mt-1 text-xl font-semibold">{recommendation.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{recommendation.description}</p>{delta ? <div className="mt-4 rounded-xl border border-green-100 bg-green-50 px-3 py-2"><span className="block text-[11px] uppercase tracking-wide text-green-700">Projected impact</span><strong className="text-lg text-green-800">{delta}</strong></div> : null}{recommendations.length > 1 ? <p className="mt-4 rounded-xl bg-slate-50 px-3 py-2 text-xs leading-5 text-slate-600">{recommendations.length} recommendations{campaignNames.length ? ` · ${campaignNames.join(" · ")}` : ""}</p> : recommendation.campaignName || recommendation.adGroupName ? <p className="mt-4 rounded-xl bg-slate-50 px-3 py-2 text-xs text-slate-600">{[recommendation.campaignName, recommendation.adGroupName].filter(Boolean).join(" · ")}</p> : null}</div><div className="flex flex-wrap items-center justify-end gap-2 border-t px-5 py-3"><Button type="button" size="sm" variant="outline" onClick={onView}>View {recommendations.length > 1 ? `${recommendations.length} recommendations` : "recommendation"}</Button><Button type="button" size="sm" className="recommendation-apply-action bg-blue-600 text-white hover:bg-blue-700" onClick={onApply}>{recommendations.length > 1 ? "Apply all" : "Apply"}</Button></div></article>; }
function RecommendationDetailPanel({ detail, googleUrl, onClose, onCreateRequest }: { detail: RecommendationDetail; googleUrl: string | null; onClose: () => void; onCreateRequest: (items: ManagedRecommendation[]) => void }) { const isApi = detail.kind === "api"; const recommendations = isApi ? detail.recommendations : []; const recommendation = isApi ? recommendations[0] : null; const item = isApi ? null : detail.item; const title = recommendation?.title || item?.title || "Recommendation"; const description = recommendation?.description || item?.description || ""; const category = recommendation?.category || item?.category || "ads_assets"; const uplift = isApi ? formatRecommendationUplift(recommendationGroupUplift(recommendations)) : null; const impact = isApi ? recommendationGroupDelta(recommendations) : null; const affected = [...new Set(recommendations.flatMap((entry) => [entry.campaignName, entry.adGroupName].filter((name): name is string => Boolean(name))))]; return <div className="fixed inset-0 z-50 flex justify-end" role="dialog" aria-modal="true" aria-labelledby="recommendation-detail-title"><button type="button" className="absolute inset-0 cursor-default bg-slate-950/45" aria-label="Close recommendation details" onClick={onClose} /><aside className="relative z-10 flex h-full w-full max-w-xl flex-col overflow-hidden bg-white shadow-2xl"><header className="flex items-start justify-between gap-4 border-b p-5"><div><p className="text-xs font-semibold uppercase tracking-wide text-blue-700">{isApi ? "Available in our app" : "Complete in Google Ads"}</p><h3 id="recommendation-detail-title" className="mt-1 text-2xl font-semibold">{title}</h3></div><Button type="button" variant="ghost" size="icon" aria-label="Close recommendation details" autoFocus onClick={onClose}><XIcon /></Button></header><div className="flex-1 space-y-5 overflow-y-auto p-5"><div><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{recommendationCategoryLabel(category)}</p><p className="mt-2 text-sm leading-6 text-slate-700">{description}</p></div>{uplift || impact ? <div className="grid gap-3 sm:grid-cols-2">{uplift ? <div className="rounded-xl bg-blue-50 p-4"><span className="text-xs text-blue-700">Optimization score</span><strong className="mt-1 block text-2xl text-blue-800">{uplift}</strong></div> : null}{impact ? <div className="rounded-xl bg-green-50 p-4"><span className="text-xs text-green-700">Projected impact</span><strong className="mt-1 block text-2xl text-green-800">{impact}</strong></div> : null}</div> : null}{isApi ? <div><h4 className="font-semibold">Affected campaigns and ad groups</h4>{affected.length ? <ul className="mt-2 space-y-2">{affected.map((name) => <li key={name} className="rounded-lg bg-slate-50 px-3 py-2 text-sm text-slate-700">{name}</li>)}</ul> : <p className="mt-2 text-sm text-slate-500">Google returned this as an account-level recommendation.</p>}</div> : <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><strong className="block">Google must confirm this recommendation</strong>The public API does not provide its current eligibility or setup details. Continue to Google Ads to see the live result for this account.</div>}</div><footer className="flex flex-wrap justify-end gap-2 border-t bg-white p-5"><Button type="button" variant="outline" onClick={onClose}>Close</Button>{googleUrl ? <Button asChild variant={isApi ? "outline" : "default"} className={isApi ? "" : "bg-blue-600 text-white hover:bg-blue-700"}><a href={googleUrl} target="_blank" rel="noreferrer">{isApi ? "Open in Google Ads" : "Continue to Google Ads"} <ArrowUpRightIcon /></a></Button> : null}{isApi ? <Button type="button" className="recommendation-apply-action bg-blue-600 text-white hover:bg-blue-700" onClick={() => onCreateRequest(recommendations)}>Create change request</Button> : null}</footer></aside></div>; }
function recommendationGroupDelta(recommendations: ManagedRecommendation[]): string | null { const clicks = recommendations.reduce((sum, recommendation) => sum + Number(recommendation.potentialMetrics?.clicks || 0) - Number(recommendation.baseMetrics?.clicks || 0), 0); if (clicks > 0) return `+${Math.round(clicks)} clicks`; const conversions = recommendations.reduce((sum, recommendation) => sum + Number(recommendation.potentialMetrics?.conversions || 0) - Number(recommendation.baseMetrics?.conversions || 0), 0); if (conversions > 0) return `+${conversions.toFixed(1)} conversions`; const impressions = recommendations.reduce((sum, recommendation) => sum + Number(recommendation.potentialMetrics?.impressions || 0) - Number(recommendation.baseMetrics?.impressions || 0), 0); return impressions > 0 ? `+${Math.round(impressions)} impressions` : null; }
function recommendationGroupUplift(recommendations: ManagedRecommendation[]): number { return recommendations.find((recommendation) => typeof recommendation.optimizationScoreUplift === "number")?.optimizationScoreUplift ?? 0; }
function recommendationCategoryUplift(recommendations: ManagedRecommendation[]): string | null { const byType = new Map<string, number>(); for (const recommendation of recommendations) if (typeof recommendation.optimizationScoreUplift === "number") byType.set(recommendation.type, recommendation.optimizationScoreUplift); return formatRecommendationUplift([...byType.values()].reduce((sum, value) => sum + value, 0)); }
function formatRecommendationUplift(value: number): string | null { if (!(value > 0)) return null; const percent = value * 100; return percent < 0.1 ? "+<0.1%" : `+${percent.toLocaleString(undefined, { maximumFractionDigits: 1 })}%`; }
function recommendationCategoryLabel(category: ManagedRecommendationCategory) { return ({ repairs: "Repairs", bidding_budgets: "Bidding & budgets", keywords_targeting: "Keywords & targeting", ads_assets: "Ads & assets", measurement: "Measurement" } as Record<ManagedRecommendationCategory, string>)[category]; }
function ServingStatusPanel({ configuredStatus, primaryStatus, reasons }: { configuredStatus: string; primaryStatus: string; reasons: string[] }) { const tone = primaryStatus === "ELIGIBLE" ? "border-green-200 bg-green-50 text-green-900" : primaryStatus === "NOT_ELIGIBLE" ? "border-red-200 bg-red-50 text-red-900" : "border-amber-200 bg-amber-50 text-amber-900"; return <div className={`rounded-2xl border p-5 ${tone}`}><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-wide opacity-70">Serving status</p><h3 className="mt-1 text-lg font-semibold">{formatStatus(primaryStatus)}</h3></div><div className="rounded-full border border-current/20 bg-white/60 px-3 py-1 text-sm">Configured: {formatStatus(configuredStatus)}</div></div><p className="mt-3 text-sm">{reasons.length ? reasons.map(formatStatus).join(" · ") : "Google returned no additional serving-status reason."}</p></div>; }
function AdStrengthPanel({ strength, actionItems }: { strength: string; actionItems: string[] }) { const tone = strength === "EXCELLENT" || strength === "GOOD" ? "border-green-200 bg-green-50" : "border-amber-200 bg-amber-50"; return <div className={`rounded-2xl border p-5 ${tone}`}><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Google ad strength</p><h3 className="mt-1 text-lg font-semibold">{formatStatus(strength)}</h3>{actionItems.length ? <ul className="mt-3 list-disc space-y-1 pl-5 text-sm text-slate-700">{actionItems.map((item) => <li key={item}>{item}</li>)}</ul> : <p className="mt-2 text-sm text-slate-600">Google returned no additional recommendation.</p>}</div>; }
function formatStatus(value: string) { return value ? value.toLowerCase().split("_").map((part) => part ? part[0].toUpperCase() + part.slice(1) : "").join(" ") : "Unknown"; }
function formatAdType(value: string) { return value.toLowerCase().split("_").map((part) => part ? part[0].toUpperCase() + part.slice(1) : "").join(" "); }
function GoogleStyleAdEditor({
  ad,
  sitelinkField,
  values,
  onChange,
  } : {
  ad: ManagedAd;
  sitelinkField?: ManagedFieldValue;
  values: Record<string, unknown>;
  onChange: (field: ManagedFieldValue, value: unknown) => void;
}) {
  const identity = ad.fields.filter((field) => field.fieldKey === "ad_group_ad.status" || field.fieldKey === "ad.name");
  const destination = ad.fields.filter((field) => field.fieldKey === "ad.final_url");
  const automation = ad.fields.filter((field) => field.valueType === "asset_automation_settings");
  const media = ad.fields.filter((field) => ["asset_ref", "asset_refs"].includes(field.valueType) && !field.fieldKey.includes("call_to_action"));
  const text = ad.fields.filter((field) => field.valueType === "text_assets" || field.valueType === "single_text_asset" || field.fieldKey.includes("business_name") || field.fieldKey.includes("call_to_action"));
  const advanced = ad.fields.filter((field) => field.valueType === "url_list" || field.valueType === "custom_parameters" || field.fieldKey.includes("tracking_url") || field.fieldKey.includes("final_url_suffix") || field.fieldKey.includes("breadcrumb") || field.fieldKey === "ad.path1" || field.fieldKey === "ad.path2");
  const used = new Set([...identity, ...destination, ...automation, ...media, ...text, ...advanced]);
  const additional = ad.fields.filter((field) => !used.has(field));
  return <div className="space-y-4">
    <AdStrengthPanel strength={ad.adStrength} actionItems={ad.actionItems} />
    <GoogleEditorCard title="Ad name" subtitle="Used internally to identify this ad"><FieldGrid fields={identity} values={values} onChange={onChange} /><p className="mt-3 text-xs text-slate-500">Google’s API makes an existing ad name immutable. Renaming requires a controlled replace-ad workflow.</p></GoogleEditorCard>
    <GoogleEditorCard title="Final URL"><FieldGrid fields={destination} values={values} onChange={onChange} /></GoogleEditorCard>
    {sitelinkField ? <GoogleEditorCard title="Sitelinks" ><FieldGrid fields={[sitelinkField]} values={values} onChange={onChange} /></GoogleEditorCard> : null}
    {media.length ? <GoogleEditorCard title="Media" subtitle="Videos, images and logos attached to this ad"><FieldGrid fields={media} values={values} onChange={onChange} /></GoogleEditorCard> : null}
    {text.length ? <GoogleEditorCard title="Text"><FieldGrid fields={text} values={values} onChange={onChange} /></GoogleEditorCard> : null}
    {automation.length ? <GoogleEditorCard title="Asset optimization" subtitle="Let Google create optimized versions of existing content"><FieldGrid fields={automation} values={values} onChange={onChange} /></GoogleEditorCard> : null}
    {advanced.length ? <GoogleEditorCard title="URL and other options" defaultOpen={false}><FieldGrid fields={advanced} values={values} onChange={onChange} /></GoogleEditorCard> : null}
    {additional.length ? <GoogleEditorCard title="Additional settings" defaultOpen={false}><FieldGrid fields={additional} values={values} onChange={onChange} /></GoogleEditorCard> : null}
  </div>;
}
function GoogleEditorCard({ title, subtitle, defaultOpen = true, children }: { title: string; subtitle?: string; defaultOpen?: boolean; children: React.ReactNode }) { const [open, setOpen] = useState(defaultOpen); return <section className="overflow-hidden rounded-2xl border bg-white shadow-sm"><button type="button" aria-expanded={open} onClick={() => setOpen((current) => !current)} className="flex w-full items-center justify-between gap-4 px-5 py-4 text-left"><span><span className="block text-lg font-semibold">{title}</span>{subtitle ? <span className="mt-0.5 block text-xs text-slate-500">{subtitle}</span> : null}</span><ChevronDownIcon className={`size-5 shrink-0 text-slate-500 transition-transform ${open ? "rotate-180" : ""}`} /></button>{open ? <div className="border-t px-5 py-5">{children}</div> : null}</section>; }
function FieldSection({ title, subtitle, fields, values, onChange }: { title: string; subtitle?: string; fields: ManagedFieldValue[]; values: Record<string, unknown>; onChange: (f: ManagedFieldValue, v: unknown) => void }) {
  return <div className="rounded-2xl border bg-white p-5 shadow-sm"><h3 className="font-semibold">{title}</h3>{subtitle ? <p className="text-xs text-slate-500">{subtitle}</p> : null}<div className="mt-4"><FieldGrid fields={fields} values={values} onChange={onChange} /></div></div>;
}
function FieldGrid({ fields, values, onChange }: { fields: ManagedFieldValue[]; values: Record<string, unknown>; onChange: (f: ManagedFieldValue, v: unknown) => void }) {
  return <div className="grid gap-4 sm:grid-cols-2">{fields.map((f) => {
    const current = values[fieldId(f)]; const displayPath = f.fieldKey === "ad.path1" || f.fieldKey === "ad.path2" || f.fieldKey.endsWith(".breadcrumb1") || f.fieldKey.endsWith(".breadcrumb2");
    if (f.valueType === "text_assets") return <TextAssetsEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "sitelinks") return <SitelinksEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "asset_refs") return <AssetRefsEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "url_list") return <StringListEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "custom_parameters") return <CustomParametersEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "asset_automation_settings") return <AssetAutomationEditor key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "money_micros") return <MoneyMicrosInput key={fieldId(f)} field={f} value={current} onChange={(value) => onChange(f, value)} />;
    if (f.valueType === "boolean") return <label key={fieldId(f)} className="flex items-center gap-3 rounded-xl border p-3"><input type="checkbox" checked={Boolean(current)} disabled={!f.editable} onChange={(event) => onChange(f, event.target.checked)} /><span className="text-sm font-medium">{f.fieldLabel}</span></label>;
    return <label key={fieldId(f)} className="space-y-1"><span className="text-sm font-medium">{f.fieldLabel}{!f.editable ? <span className="ml-2 text-xs text-slate-400">Read only</span> : null}</span>{f.fieldKey.endsWith("status") ? <select disabled={!f.editable} value={String(current ?? "")} onChange={(e) => onChange(f, e.target.value)} className="h-10 w-full rounded-md border bg-white px-3"><option value="ENABLED">Enabled</option><option value="PAUSED">Paused</option></select> : <Input type={f.valueType === "date" ? "date" : f.valueType === "url" ? "url" : "text"} maxLength={displayPath ? 15 : f.fieldKey.endsWith("business_name") ? 25 : undefined} disabled={!f.editable} value={String(current ?? "")} onChange={(e) => onChange(f, e.target.value)} />}{displayPath ? <span className="text-xs text-slate-500">{String(current ?? "").length} / 15</span> : null}</label>;
  })}</div>;
}
function MoneyMicrosInput({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (micros: string) => void }) { const amount = Number(value ?? 0) / 1_000_000; const dailyBudget = field.fieldKey === "campaign_budget.amount_micros"; return <label className="space-y-1"><span className="text-sm font-medium">{field.fieldLabel} ({dailyBudget ? "MYR/day" : "MYR"}){!field.editable ? <span className="ml-2 text-xs text-slate-400">Read only</span> : null}</span><div className="flex overflow-hidden rounded-md border bg-white focus-within:ring-2 focus-within:ring-blue-200"><span className="flex items-center border-r bg-slate-50 px-3 text-sm font-medium text-slate-600">MYR</span><input className="h-10 min-w-0 flex-1 px-3 outline-none disabled:bg-slate-100" type="number" min="0.01" step="0.01" disabled={!field.editable} value={Number.isFinite(amount) ? amount : ""} onChange={(event) => { const next = Number(event.target.value); onChange(Number.isFinite(next) ? String(Math.round(next * 1_000_000)) : "0"); }} /><span className="flex items-center border-l bg-slate-50 px-3 text-sm text-slate-500">{dailyBudget ? "/day" : ""}</span></div><span className="text-xs text-slate-500">Google stores this amount internally in micros.</span></label>; }
function TextAssetsEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: ManagedAdTextAsset[]) => void }) { const assets = Array.isArray(value) ? value as ManagedAdTextAsset[] : []; const headlines = field.fieldKey.endsWith("headlines"); const rsa = field.fieldKey === "ad.headlines" || field.fieldKey === "ad.descriptions"; const maxItems = rsa ? (headlines ? 15 : 4) : 5; const demandGenVideoHeadline = field.fieldKey.includes("demand_gen_video_responsive_ad") && headlines && !field.fieldKey.endsWith("long_headlines"); const charMax = field.fieldKey.endsWith("long_headlines") || !headlines ? 90 : demandGenVideoHeadline ? 40 : 30; function update(index: number, text: string) { const current = assets[index]; const next = [...assets]; next[index] = { text, ...(current?.pinnedField ? { pinnedField: current.pinnedField } : {}) }; onChange(next); } function add() { if (assets.length < maxItems) onChange([...assets, { text: "" }]); } function remove(index: number) { onChange(assets.filter((_, itemIndex) => itemIndex !== index)); } return <div className="space-y-2 sm:col-span-2"><div className="flex items-center justify-between"><span className="text-sm font-medium">{field.fieldLabel} {assets.length}/{maxItems}</span><Button type="button" size="sm" variant="outline" disabled={assets.length >= maxItems} onClick={add}>Add {headlines ? "headline" : "description"}</Button></div>{assets.map((asset, index) => <div key={`${field.fieldKey}-${index}`} className="rounded-xl border p-3"><div className="flex gap-2"><Input value={asset.text || ""} maxLength={charMax} onChange={(e) => update(index, e.target.value)} /><Button type="button" size="sm" variant="outline" onClick={() => remove(index)}>Remove</Button></div><div className="mt-1 flex justify-between text-xs text-slate-500"><span>{asset.pinnedField ? `Required · ${asset.pinnedField}` : "Unpinned"}</span><span>{asset.text?.length ?? 0} / {charMax}</span></div></div>)}</div>; }
function SitelinksEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: ManagedSitelink[]) => void }) {
  const items = Array.isArray(value) ? value as ManagedSitelink[] : [];
  const targets = field.sitelinkTargets?.length ? field.sitelinkTargets : field.sitelinkTarget ? [{ ...field.sitelinkTarget, label: "Ad group" }] : [];
  const defaultTarget = targets.find((target) => target.scope === "campaign") ?? targets[0];
  function update(index: number, values: Partial<ManagedSitelink>) {
    if (!items[index]?.editable) return;
    onChange(items.map((item, itemIndex) => itemIndex === index ? { ...item, ...values } : item));
  }
  function add() {
    if (!defaultTarget || items.length >= 20) return;
    const association: ManagedSitelinkAssociation = { linkResourceName: "", scope: defaultTarget.scope, targetResourceName: defaultTarget.resourceName, status: "ENABLED" };
    onChange([...items, { id: `draft-sitelink-${Date.now()}`, scope: defaultTarget.scope, targetResourceName: defaultTarget.resourceName, source: "ADVERTISER", status: "ENABLED", linkText: "", description1: "", description2: "", finalUrls: [""], finalMobileUrls: [], startDate: "", endDate: "", editable: true, associations: [association] }]);
  }
  function associations(item: ManagedSitelink): ManagedSitelinkAssociation[] {
    return item.associations?.length ? item.associations : [{ linkResourceName: item.linkResourceName || "", scope: item.scope, targetResourceName: item.targetResourceName, status: item.status }];
  }
  function removeAssociation(itemIndex: number, associationIndex: number) {
    const item = items[itemIndex];
    if (!item?.editable) return;
    const remaining = associations(item).filter((_, index) => index !== associationIndex);
    if (!remaining.length) {
      onChange(items.filter((_, index) => index !== itemIndex));
      return;
    }
    onChange(items.map((candidate, index) => index === itemIndex ? { ...candidate, scope: remaining[0].scope, targetResourceName: remaining[0].targetResourceName, linkResourceName: remaining[0].linkResourceName, associations: remaining } : candidate));
  }
  function changeDraftScope(index: number, scope: ManagedSitelinkScope) {
    const target = targets.find((candidate) => candidate.scope === scope);
    if (!target) return;
    const association: ManagedSitelinkAssociation = { linkResourceName: "", scope, targetResourceName: target.resourceName, status: "ENABLED" };
    update(index, { scope, targetResourceName: target.resourceName, associations: [association] });
  }
  return <div className="space-y-3 sm:col-span-2">
    <div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-sm font-medium">{items.length} sitelink{items.length === 1 ? "" : "s"}</p><p className="text-xs text-slate-500">New sitelinks default to campaign level. Publishing always validates and checks Google for conflicts.</p></div><Button type="button" size="sm" variant="outline" disabled={!defaultTarget || items.length >= 20} onClick={add}>Add sitelink</Button></div>
    {!items.length ? <div className="rounded-xl border border-dashed p-5 text-center text-sm text-slate-500">No sitelinks are currently attached. Select Add sitelink to create one.</div> : items.map((item, index) => {
      const itemAssociations = associations(item);
      const isDraft = item.id.startsWith("draft-sitelink-");
      return <div key={item.id || index} className="rounded-xl border bg-slate-50/50 p-4">
        <div className="mb-3"><p className="font-medium">{item.linkText || `New sitelink ${index + 1}`}</p>{!item.editable ? <p className="text-xs text-slate-500">Automatically created by Google</p> : null}</div>
        {isDraft ? <label className="mb-3 block space-y-1"><span className="text-xs font-medium">Attach new sitelink to</span><select className="h-9 w-full rounded-md border bg-white px-3 text-sm" value={item.scope} onChange={(event) => changeDraftScope(index, event.target.value as ManagedSitelinkScope)}>{targets.map((target) => <option key={`${target.scope}:${target.resourceName}`} value={target.scope}>{target.label}</option>)}</select></label> : null}
        <div className="mb-3 space-y-2"><p className="text-xs font-medium text-slate-600">Google Ads associations</p>{itemAssociations.map((association, associationIndex) => { const inherited = association.scope !== "ad_group"; return <div key={association.linkResourceName || `${association.scope}:${association.targetResourceName}`} className="flex items-center justify-between gap-3 rounded-lg border bg-white px-3 py-2"><div><p className="text-sm">{association.scope === "customer" ? "Account" : association.scope === "campaign" ? "Campaign" : "Ad group"}</p><p className="text-xs text-slate-500">{inherited ? "Can appear in child campaigns or ad groups" : "Attached directly to this ad group"}</p></div><Button type="button" size="sm" variant="outline" disabled={!item.editable} onClick={() => removeAssociation(index, associationIndex)}>Remove from {association.scope === "customer" ? "account" : association.scope === "campaign" ? "campaign" : "ad group"}</Button></div>; })}{itemAssociations.length > 1 ? <p className="text-xs text-amber-700">Removing one association will not remove this sitelink from the other listed locations.</p> : null}</div>
        <div className="grid gap-3 sm:grid-cols-2">
          <label className="space-y-1"><span className="text-xs font-medium">Sitelink text</span><Input disabled={!item.editable} maxLength={25} value={item.linkText} onChange={(event) => update(index, { linkText: event.target.value })} /><span className="block text-right text-xs text-slate-500">{item.linkText.length} / 25</span></label>
          <label className="space-y-1"><span className="text-xs font-medium">Final URL</span><Input type="url" disabled={!item.editable} placeholder="https://example.com/page" value={item.finalUrls[0] || ""} onChange={(event) => update(index, { finalUrls: [event.target.value] })} /></label>
          <label className="space-y-1"><span className="text-xs font-medium">Description line 1</span><Input disabled={!item.editable} maxLength={35} value={item.description1} onChange={(event) => update(index, { description1: event.target.value })} /><span className="block text-right text-xs text-slate-500">{item.description1.length} / 35</span></label>
          <label className="space-y-1"><span className="text-xs font-medium">Description line 2</span><Input disabled={!item.editable} maxLength={35} value={item.description2} onChange={(event) => update(index, { description2: event.target.value })} /><span className="block text-right text-xs text-slate-500">{item.description2.length} / 35</span></label>
          <label className="space-y-1"><span className="text-xs font-medium">Mobile final URL (optional)</span><Input type="url" disabled={!item.editable} value={item.finalMobileUrls[0] || ""} onChange={(event) => update(index, { finalMobileUrls: event.target.value ? [event.target.value] : [] })} /></label>
          <div className="grid grid-cols-2 gap-2"><label className="space-y-1"><span className="text-xs font-medium">Start date</span><Input type="date" disabled={!item.editable} value={item.startDate} onChange={(event) => update(index, { startDate: event.target.value })} /></label><label className="space-y-1"><span className="text-xs font-medium">End date</span><Input type="date" disabled={!item.editable} value={item.endDate} onChange={(event) => update(index, { endDate: event.target.value })} /></label></div>
        </div>
      </div>;
    })}
  </div>;
}
function AssetRefsEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: string[]) => void }) { const refs = Array.isArray(value) ? value.map(String) : []; function update(index: number, nextValue: string) { const next = [...refs]; next[index] = nextValue; onChange(next); } return <div className="space-y-2 sm:col-span-2"><div className="flex items-center justify-between"><span className="text-sm font-medium">{field.fieldLabel}</span><Button type="button" size="sm" variant="outline" onClick={() => onChange([...refs, ""])}>Add asset</Button></div>{refs.map((ref, index) => { const asset = field.assetOptions?.find((candidate) => candidate.resourceName === ref); const previewUrl = asset?.imageUrl || (asset?.youtubeVideoId ? `https://i.ytimg.com/vi/${asset.youtubeVideoId}/mqdefault.jpg` : ""); return <div key={`${field.fieldKey}-${index}`} className="rounded-xl border p-3"><div className="flex items-center gap-3">{previewUrl ? <div role="img" aria-label={asset?.name || "Asset preview"} className="h-16 w-24 shrink-0 rounded-lg bg-cover bg-center" style={{ backgroundImage: `url(${JSON.stringify(previewUrl)})` }} /> : <div className="grid h-16 w-24 shrink-0 place-items-center rounded-lg bg-slate-100 text-xs text-slate-500">{asset?.type ? formatAdType(asset.type) : "Asset"}</div>}<div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{asset?.youtubeVideoTitle || (asset?.callToAction ? formatAdType(asset.callToAction) : "") || asset?.name || "Google Ads asset"}</p><p className="truncate text-xs text-slate-500">{asset ? formatAdType(asset.type) : "Paste a Google Ads asset resource name"}</p><Input className="mt-2 font-mono text-xs" value={ref} placeholder="customers/1234567890/assets/123" onChange={(event) => update(index, event.target.value)} /></div><Button type="button" size="sm" variant="outline" onClick={() => onChange(refs.filter((_, itemIndex) => itemIndex !== index))}>Remove</Button></div></div>; })}</div>; }
function StringListEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: string[]) => void }) { const items = Array.isArray(value) ? value.map(String) : []; return <div className="space-y-2 sm:col-span-2"><div className="flex items-center justify-between"><span className="text-sm font-medium">{field.fieldLabel}</span><Button type="button" size="sm" variant="outline" onClick={() => onChange([...items, ""])}>Add URL</Button></div>{items.length ? items.map((item, index) => <div key={`${field.fieldKey}-${index}`} className="flex gap-2"><Input type="url" value={item} onChange={(event) => { const next = [...items]; next[index] = event.target.value; onChange(next); }} /><Button type="button" size="sm" variant="outline" onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}>Remove</Button></div>) : <p className="rounded-xl border border-dashed p-3 text-sm text-slate-500">The regular final URL is used on mobile.</p>}</div>; }
function CustomParametersEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: ManagedCustomParameter[]) => void }) { const items = Array.isArray(value) ? value as ManagedCustomParameter[] : []; return <div className="space-y-2 sm:col-span-2"><div className="flex items-center justify-between"><span className="text-sm font-medium">{field.fieldLabel}</span><Button type="button" size="sm" variant="outline" onClick={() => onChange([...items, { key: "", value: "" }])}>Add parameter</Button></div>{items.map((item, index) => <div key={`${field.fieldKey}-${index}`} className="grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><Input aria-label={`Custom parameter ${index + 1} name`} placeholder="Name" value={item.key || ""} onChange={(event) => { const next = [...items]; next[index] = { ...item, key: event.target.value }; onChange(next); }} /><Input aria-label={`Custom parameter ${index + 1} value`} placeholder="Value" value={item.value || ""} onChange={(event) => { const next = [...items]; next[index] = { ...item, value: event.target.value }; onChange(next); }} /><Button type="button" size="sm" variant="outline" onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))}>Remove</Button></div>)}</div>; }
function AssetAutomationEditor({ field, value, onChange }: { field: ManagedFieldValue; value: unknown; onChange: (value: ManagedAssetAutomationSetting[]) => void }) { const current = Array.isArray(value) ? value as ManagedAssetAutomationSetting[] : []; const defaults: ManagedAssetAutomationSetting[] = [{ assetAutomationType: "GENERATE_SHORTER_YOUTUBE_VIDEOS", assetAutomationStatus: "OPTED_IN" }, { assetAutomationType: "GENERATE_VERTICAL_YOUTUBE_VIDEOS", assetAutomationStatus: "OPTED_IN" }, { assetAutomationType: "GENERATE_LANDING_PAGE_PREVIEW", assetAutomationStatus: "OPTED_OUT" }, { assetAutomationType: "GENERATE_LANDING_PAGE_TEXT", assetAutomationStatus: "OPTED_IN" }]; const settings = defaults.map((fallback) => current.find((item) => item.assetAutomationType === fallback.assetAutomationType) || fallback); return <div className="space-y-2 sm:col-span-2"><span className="text-sm font-medium">{field.fieldLabel}</span>{settings.map((setting) => <label key={setting.assetAutomationType} className="flex items-center justify-between rounded-xl border p-3"><span className="text-sm">{automationLabel(setting.assetAutomationType)}</span><input type="checkbox" checked={setting.assetAutomationStatus === "OPTED_IN"} onChange={(event) => onChange(settings.map((item) => item.assetAutomationType === setting.assetAutomationType ? { ...item, assetAutomationStatus: event.target.checked ? "OPTED_IN" : "OPTED_OUT" } : item))} /></label>)}</div>; }
function automationLabel(value: string) { const labels: Record<string, string> = { GENERATE_SHORTER_YOUTUBE_VIDEOS: "Create shorter videos", GENERATE_VERTICAL_YOUTUBE_VIDEOS: "Create resized vertical videos", GENERATE_LANDING_PAGE_PREVIEW: "Use landing-page image previews", GENERATE_LANDING_PAGE_TEXT: "Use landing-page text" }; return labels[value] || formatAdType(value); }
function fieldId(f: Pick<ManagedFieldValue, "entityType" | "entityId" | "fieldKey">) { return `${f.entityType}:${f.entityId}:${f.fieldKey}`; }
function latestEditorContext(changeSet: AdsChangeSetRecord): DraftEditorContext | null {
  const events = [...(changeSet.ads_change_events ?? [])].sort((left, right) => String(right.created_at ?? "").localeCompare(String(left.created_at ?? "")));
  for (const event of events) {
    const metadata = event.metadata && typeof event.metadata === "object" ? event.metadata as Record<string, unknown> : null;
    const value = metadata?.editorContext;
    if (!value || typeof value !== "object") continue;
    const context = value as Record<string, unknown>;
    if (!["campaigns", "ad_groups", "ads"].includes(String(context.view)) || typeof context.campaignId !== "string") continue;
    return { view: context.view as DraftEditorContext["view"], campaignId: context.campaignId, ...(typeof context.adGroupId === "string" ? { adGroupId: context.adGroupId } : {}), ...(typeof context.adId === "string" ? { adId: context.adId } : {}) };
  }
  return null;
}
function findChangeLocation(campaigns: ManagedCampaign[], change: { entity_type: string; entity_id: string; field_key: string }) {
  const matchesField = (field: ManagedFieldValue) => field.entityType === change.entity_type && field.entityId === change.entity_id && field.fieldKey === change.field_key;
  for (const campaign of campaigns) {
    if (campaign.fields.some(matchesField) || (change.entity_type === "campaign" && [campaign.id, campaign.resourceName, campaign.budgetResourceName].includes(change.entity_id))) return { campaign, adGroup: null, ad: null };
    for (const adGroup of campaign.adGroups) {
      if (adGroup.fields.some(matchesField) || (change.entity_type === "ad_group" && [adGroup.id, adGroup.resourceName].includes(change.entity_id))) return { campaign, adGroup, ad: null };
      for (const ad of adGroup.ads) if (ad.fields.some(matchesField) || (change.entity_type === "ad" && [ad.id, ad.resourceName].includes(change.entity_id))) return { campaign, adGroup, ad };
    }
  }
  return null;
}
function normalizeDraftValue(field: ManagedFieldValue, value: unknown): unknown { if (["string", "url", "date", "single_text_asset", "asset_ref"].includes(field.valueType)) return String(value ?? "").trim(); if (["asset_refs", "url_list"].includes(field.valueType) && Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean); if (field.valueType === "custom_parameters" && Array.isArray(value)) return (value as ManagedCustomParameter[]).flatMap((item) => { const key = String(item?.key || "").trim(); const parameterValue = String(item?.value || "").trim(); return key || parameterValue ? [{ key, value: parameterValue }] : []; }); if (field.valueType === "text_assets" && Array.isArray(value)) return (value as ManagedAdTextAsset[]).flatMap((asset) => { const text = typeof asset?.text === "string" ? asset.text.trim() : ""; return text ? [{ text, ...(asset.pinnedField ? { pinnedField: asset.pinnedField } : {}) }] : []; }); if (field.valueType === "sitelinks" && Array.isArray(value)) return (value as ManagedSitelink[]).map((item) => ({ ...item, linkText: item.linkText.trim(), description1: item.description1.trim(), description2: item.description2.trim(), finalUrls: item.finalUrls.map((url) => url.trim()).filter(Boolean), finalMobileUrls: item.finalMobileUrls.map((url) => url.trim()).filter(Boolean), startDate: item.startDate.trim(), endDate: item.endDate.trim() })); return value; }
function managementAccountLabel(accountName: string) { return accountName.replace(/^Google\s*-\s*/i, "").replace(/\s*\|\s*\d{3}-?\d{3}-?\d{4}\s*$/, "").trim() || accountName; }
function defaultManagementDateRange(startDate: string | null, endDate: string | null) {
  const valid = (value: string | null) => Boolean(value && /^\d{4}-\d{2}-\d{2}$/.test(value));
  if (valid(startDate) && valid(endDate) && startDate! <= endDate!) return { startDate: startDate!, endDate: endDate! };

  const today = new Date();
  const end = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const start = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 29);
  const iso = (value: Date) => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;

  return { startDate: iso(start), endDate: iso(end) };
}
function PageMessage({ text, loading }: { text: string; loading?: boolean }) { return <main className="grid min-h-screen place-items-center bg-slate-50 p-6"><div className="rounded-2xl border bg-white p-8 text-center shadow-sm">{loading ? <Loader2Icon className="mx-auto mb-3 animate-spin" /> : null}<p>{text}</p><Button asChild variant="outline" className="mt-4"><Link href="/">Back to account search</Link></Button></div></main>; }
